  "rewrite_sql": "-- Safe migration: add token column with random() default
-- Original: ALTER TABLE order_items ADD COLUMN token double precision DEFAULT random();
-- Problem: DEFAULT random() on ADD COLUMN forces full table rewrite
-- Solution: Add nullable column, backfill in batches, then set default

-- Step 1: Add column without default (metadata-only, no rewrite)
SET lock_timeout = '2s';
SET statement_timeout = '10s';
ALTER TABLE order_items ADD COLUMN IF NOT EXISTS token double precision;

-- Step 2: Backfill existing rows in batches
-- Using a procedure to commit between batches and release locks
CREATE OR REPLACE PROCEDURE backfill_order_items_token()
LANGUAGE plpgsql
AS $$
DECLARE
  batch_size INTEGER := 1000;
  rows_updated INTEGER;
BEGIN
  LOOP
    UPDATE order_items
    SET token = random()
    WHERE id IN (
      SELECT id FROM order_items
      WHERE token IS NULL
      ORDER BY id
      LIMIT batch_size
    );
    GET DIAGNOSTICS rows_updated = ROW_COUNT;
    EXIT WHEN rows_updated = 0;
    COMMIT;
  END LOOP;
END $$;

CALL backfill_order_items_token();
DROP PROCEDURE backfill_order_items_token();

-- Step 3: Set default for future inserts (metadata-only)
SET lock_timeout = '2s';
SET statement_timeout = '10s';
ALTER TABLE order_items ALTER COLUMN token SET DEFAULT random();",
